-- Full administrative catalogue v2: official post-2025 two-tier divisions
-- (34 provinces, 3,321 commune-level units; National Statistics Office data,
-- package vietnam-provinces 2026.9.0). Replaces the v1 demo subset (39 units).
--
-- BREAKING: every v1 ward code (WARD-*) is retired and province Hue changes
-- 75 -> 46. Saved addresses and street mappings that reference retired codes
-- are removed first (their ward/province no longer exists); orders keep their
-- address name snapshots and are not touched. Deploy inside the catalogue
-- maintenance window (see docs/06_operations/catalogue-change-runbook.md).
DELETE FROM street_ward_mappings;
DELETE FROM shipping_addresses;
DELETE FROM administrative_units;


